ARTIFACT_TTL = 7 * 24 * 60 * 60
AUDIT_TTL = 30 * 24 * 60 * 60

def download(created_at, now, url):
    if now - created_at > ARTIFACT_TTL:
        return 410, None
    return 200, url

def total_amount(items):
    result = 0
    for amount in items:
        result += amount
    return result

