import unittest
from service import download, total_amount, ARTIFACT_TTL, AUDIT_TTL

class ServiceTests(unittest.TestCase):
    def test_fresh(self):
        self.assertEqual(download(100, 101, "file"), (200, "file"))
    def test_expired(self):
        self.assertEqual(download(0, ARTIFACT_TTL + 1, "file"), (410, None))
    def test_audit(self):
        self.assertEqual(AUDIT_TTL, 30 * 24 * 60 * 60)
    def test_total(self):
        self.assertEqual(total_amount([1, 2, 3]), 6)
        self.assertEqual(total_amount([]), 0)

